import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "src", label: "Default image URL", value: "/assets/example-960.webp", full: true })}${field({ id: "alt", label: "Alt text", value: "Screenshot of the example tool", full: true })}${field({ id: "width", label: "Width", value: "960", type: "number" })}${field({ id: "height", label: "Height", value: "540", type: "number" })}${textarea({ id: "srcset", label: "srcset candidates", value: "/assets/example-640.webp 640w\n/assets/example-960.webp 960w\n/assets/example-1280.webp 1280w" })}${field({ id: "sizes", label: "sizes", value: "(max-width: 760px) 100vw, 760px", full: true })}${checkbox({ id: "picture", label: "Generate picture element with WebP source" })}${checkbox({ id: "lazy", label: "Lazy load image", checked: true })}</div>`,generate(root) {const src = root.querySelector("#src").value.trim();const alt = root.querySelector("#alt").value.trim();const width = root.querySelector("#width").value.trim();const height = root.querySelector("#height").value.trim();const srcset = root.querySelector("#srcset").value.split(/\r?\n/).map((line) => line.trim()).filter(Boolean).join(",\n ");const sizes = root.querySelector("#sizes").value.trim();const lazy = root.querySelector("#lazy").checked;const attrs = [`src="${attrEscape(src)}"`,srcset ? `srcset="${attrEscape(srcset.replace(/\n\s*/g, " "))}"` : "",sizes ? `sizes="${attrEscape(sizes)}"` : "",`width="${attrEscape(width)}"`,`height="${attrEscape(height)}"`,`alt="${attrEscape(alt)}"`,lazy ? `loading="lazy"` : `loading="eager"`,`decoding="async"`].filter(Boolean).join("\n ");const img = `<img\n ${attrs}\n>`;if (!root.querySelector("#picture").checked) return { output: img };return {output: `<picture>\n <source type="image/webp" srcset="${attrEscape(srcset.replace(/\n\s*/g, " "))}" sizes="${attrEscape(sizes)}">\n ${img.replace(/\n/g, "\n ")}\n</picture>`};}};